namespace QiDesk {
public partial class ManagerWindow {
    public void ShowComponentPicker(Rect? bounds=null){var window=Ui.Dialog("选择桌面组件",850,710,this);window.WindowStartupLocation=WindowStartupLocation.CenterScreen;window.Content=new ScrollViewer(){Content=ComponentLibrary(bounds,window),VerticalScrollBarVisibility=ScrollBarVisibility.Auto,Margin=new Thickness(24)};window.ShowDialog();}
    StackPanel ComponentLibrary(Rect? bounds,Window picker){
        var data=controller.Store.Data;var p=SettingsPage("组件功能区","左键选择你喜欢的组件，自由组合成自己的桌面。");var actions=new WrapPanel();p.Children.Add(actions);
        actions.Children.Add(Ui.Button("安装组件 / 组合包",delegate{InstallComponentFile(picker??this);}));actions.Children.Add(Ui.Button("制作自己的插件",delegate{CreateComponentPlugin(picker??this);}));actions.Children.Add(Ui.Button("导出桌面组合",delegate{ExportComponentSelection(picker??this);}));actions.Children.Add(Ui.Button("操作教程",delegate{ShowTutorial();}));
        if(bounds.HasValue)p.Children.Add(Ui.Text("组件会从刚才框选的区域开始排列；放不下时继续排到下一页。",12,Ui.Muted));
        var selected=new List<Tuple<CheckBox,string>>();var grid=new WrapPanel();p.Children.Add(grid);
        foreach(var plugin in WidgetPlugins.All(data)){
            var item=plugin;var content=new StackPanel();var check=new CheckBox(){IsEnabled=item.Enabled,Content=item.Name,FontSize=17,Foreground=Ui.Ink,Margin=new Thickness(0,0,0,10)};selected.Add(Tuple.Create(check,item.Id));content.Children.Add(check);
            content.Children.Add(new Border(){Background=new LinearGradientBrush(Color.FromRgb(38,51,74),Color.FromRgb(23,34,53),45),BorderBrush=Ui.Brush(item.Accent),BorderThickness=new Thickness(1.5),CornerRadius=new CornerRadius(16),Height=78,Margin=new Thickness(0,0,0,12),Child=new TextBlock(){Text=ComponentCaption(item),FontSize=21,Foreground=Ui.DesktopInk,TextAlignment=TextAlignment.Center,VerticalAlignment=VerticalAlignment.Center,TextTrimming=TextTrimming.CharacterEllipsis,Margin=new Thickness(10)}});
            content.Children.Add(Ui.Text(item.Description,11,Ui.Muted));var buttons=new WrapPanel();var addButton=Ui.Button("＋ 添加",delegate{AddComponentPlugins(new[]{item.Id},bounds);if(picker!=null)picker.Close();});addButton.IsEnabled=item.Enabled;buttons.Children.Add(addButton);
            if(data.Plugins.Contains(item)){buttons.Children.Add(Ui.Button(item.Enabled?"停用":"启用",delegate{controller.Store.Checkpoint();item.Enabled=!item.Enabled;SaveSettings(true);if(picker!=null)picker.Close();else ShowSettingsPage("插件与组件");}));buttons.Children.Add(Ui.Button("分享",delegate{var save=new SaveFileDialog(){Title="导出组件插件",Filter="栖桌组件插件|*.qidesk-plugin.json",FileName=item.Id+".qidesk-plugin.json"};if(save.ShowDialog(picker??this)==true)File.WriteAllText(save.FileName,Store.Json.Serialize(PluginManifest.From(item)));}));buttons.Children.Add(Ui.Button("移除",delegate{controller.Store.Checkpoint();data.Plugins.Remove(item);data.Widgets.RemoveAll(w=>w.PluginId==item.Id);data.ComponentPacks.RemoveAll(pack=>pack.components.Any(w=>w.pluginId==item.Id));SaveSettings(true);if(picker!=null)picker.Close();else ShowSettingsPage("插件与组件");}));}
            content.Children.Add(buttons);var tile=new Border(){Child=content,Width=228,MinHeight=215,Background=Ui.Surface,Padding=new Thickness(16),Margin=new Thickness(0,12,14,0),CornerRadius=new CornerRadius(20),BorderBrush=Brushes.White,BorderThickness=new Thickness(1)};grid.Children.Add(tile);
        }
        var compose=new WrapPanel(){Margin=new Thickness(0,8,0,0)};p.Children.Insert(p.Children.IndexOf(grid),compose);compose.Children.Add(Ui.Button("添加勾选的组件",delegate{var ids=selected.Where(x=>x.Item1.IsChecked==true).Select(x=>x.Item2).ToArray();if(ids.Length==0){Ui.Info("先勾选几个喜欢的组件。",picker??this);return;}AddComponentPlugins(ids,bounds);if(picker!=null)picker.Close();}));
        compose.Children.Add(Ui.Button("保存勾选项为组合",delegate{var ids=selected.Where(x=>x.Item1.IsChecked==true).Select(x=>x.Item2).ToArray();if(ids.Length==0){Ui.Info("先勾选要组合的组件。",picker??this);return;}string name=Ui.Ask("保存组合","给这套组合取个名字","我的桌面组合",picker??this);if(String.IsNullOrWhiteSpace(name))return;try{var pack=ComponentPackages.FromPlugins(data,ids,name);controller.Store.Checkpoint();ComponentPackages.Install(data,pack);SaveSettings(false);SetStatus("组合已保存，可反复添加和导出分享。");if(picker!=null)picker.Close();else ShowSettingsPage("插件与组件");}catch(Exception ex){Ui.Info(ex.Message,picker??this);}}));
        Section(p,"我的组合");foreach(var pack in data.ComponentPacks){var item=pack;var row=new WrapPanel();row.Children.Add(Ui.Text(item.name+" · "+item.components.Count+" 个组件",13,Ui.Ink));row.Children.Add(Ui.Button("添加整套",delegate{AddComponentPack(item,bounds);if(picker!=null)picker.Close();}));row.Children.Add(Ui.Button("导出分享",delegate{SaveComponentPack(item,picker??this);}));row.Children.Add(Ui.Button("移除组合",delegate{controller.Store.Checkpoint();data.ComponentPacks.Remove(item);SaveSettings(false);if(picker!=null)picker.Close();else ShowSettingsPage("插件与组件");}));p.Children.Add(row);}if(data.ComponentPacks.Count==0)p.Children.Add(Ui.Text("勾选组件后保存组合，或安装朋友分享的组合包。",12,Ui.Muted));
        Section(p,"桌面上的组件");foreach(var widget in data.Widgets.ToArray()){var item=widget;var row=new WrapPanel();row.Children.Add(Ui.Text(item.Name+" · 第 "+(item.Page+1)+" 页",13,Ui.Ink));row.Children.Add(Ui.Button("设置",delegate{EditWidget(item);}));row.Children.Add(Ui.Button("移除",delegate{controller.Store.Checkpoint();data.Widgets.Remove(item);SaveSettings(true);if(picker!=null)picker.Close();else ShowSettingsPage("插件与组件");}));p.Children.Add(row);}return p;
    }
    static string ComponentCaption(WidgetPlugin p){if(p.Kind=="clock")return "09:41";if(p.Kind=="calendar")return DateTime.Today.ToString("M 月 · d 日");if(p.Kind=="weather")return "23° · 晴间多云";if(p.Kind=="focus")return "25:00";if(p.Kind=="tasks")return "□ 今天想做的事";if(p.Kind=="choice")return "今天选哪个？";if(p.Kind=="countdown")return "还有 7 天";if(p.Kind=="calc")return "1 + 2 = 3";if(p.Kind=="habit")return "✓ 连续 7 天";if(p.Kind=="system")return "CPU 23% · 内存 61%";if(p.Kind=="photos")return "🖼 照片轮播";return String.IsNullOrEmpty(p.Text)?"写下一个想法":p.Text.Split('\n')[0];}
    public void AddComponentPlugins(IEnumerable<string> ids,Rect? bounds=null){try{AddComponentPack(ComponentPackages.FromPlugins(controller.Store.Data,ids,"临时组合"),bounds);}catch(Exception ex){Ui.Info(ex.Message,this);}}
    void AddComponentPack(ComponentPack pack,Rect? bounds){string before=Store.Json.Serialize(controller.Store.Data);try{controller.Store.Checkpoint();var added=ComponentPackages.Add(controller.Store.Data,pack,Shell.WorkingAreas(this),bounds);SaveSettings(true);if(!controller.Running)controller.Start(true);SetStatus("已添加 "+added.Count+" 个组件，可拖动、设置或撤销。");}catch(Exception ex){controller.Store.Data=Store.Json.Deserialize<State>(before);Ui.Info(ex.Message,this);}}
    void InstallComponentFile(Window owner){var picker=new OpenFileDialog(){Title="安装组件插件或组合包",Filter="栖桌组件与组合|*.qidesk-plugin.json;*.qidesk-pack.json;*.json"};if(picker.ShowDialog(owner)!=true)return;
        try{if(new FileInfo(picker.FileName).Length>1024*1024)throw new InvalidDataException("组件文件不能超过 1 MB。");var raw=Store.Json.Deserialize<Dictionary<string,object>>(File.ReadAllText(picker.FileName));bool isPack=raw.ContainsKey("format");ComponentPack pack=isPack?ComponentPackages.Read(picker.FileName):null;WidgetPlugin plugin=isPack?null:WidgetPlugins.Read(picker.FileName);var preview=Ui.Dialog("安装预览",540,470,owner);var body=new StackPanel(){Margin=new Thickness(24)};body.Children.Add(Ui.Text(isPack?pack.name:plugin.Name,22,Ui.Ink));body.Children.Add(Ui.Text(isPack?String.Join(" · ",pack.components.Select(x=>x.name)):plugin.Description,13,Ui.Muted));body.Children.Add(Ui.Text(isPack?"安装后保存在组合库，可选择添加整套或导出分享。":"安装后会出现在组件功能区，可以添加多个实例。",12,Ui.Muted));
            if(isPack)foreach(var item in pack.components.Take(8))body.Children.Add(Ui.Text("＋ "+item.name,14,Ui.Ink));else body.Children.Add(new Border(){Child=Ui.Text(ComponentCaption(plugin),20,Ui.Ink),Background=Ui.Brush(plugin.Accent),Padding=new Thickness(18),CornerRadius=new CornerRadius(16)});
            body.Children.Add(Ui.Button("安装到组件库",delegate{try{controller.Store.Checkpoint();if(isPack)ComponentPackages.Install(controller.Store.Data,pack);else WidgetPlugins.Import(controller.Store.Data,plugin);SaveSettings(false);preview.Close();if(owner!=this)owner.Close();else ShowSettingsPage("插件与组件");SetStatus("安装完成，在组件功能区选择添加即可。");}catch(Exception ex){Ui.Info(ex.Message,preview);}}));preview.Content=new ScrollViewer(){Content=body};preview.ShowDialog();
        }catch(Exception ex){Ui.Info("安装未完成："+ex.Message,owner);}
    }
    void SaveComponentPack(ComponentPack pack,Window owner){var picker=new SaveFileDialog(){Title="导出桌面组合包",Filter="栖桌桌面组合|*.qidesk-pack.json",FileName="my-desktop.qidesk-pack.json"};if(picker.ShowDialog(owner)==true){ComponentPackages.Validate(pack);File.WriteAllText(picker.FileName,Store.Json.Serialize(pack));SetStatus("组合已导出，可发给朋友导入安装。");}}
    void ExportComponentSelection(Window owner){var widgets=controller.Store.Data.Widgets.ToArray();if(widgets.Length==0){Ui.Info("先添加几个组件，或勾选组件保存为组合。",owner);return;}var window=Ui.Dialog("选择要分享的组件",520,560,owner);var body=new StackPanel(){Margin=new Thickness(24)};body.Children.Add(Ui.Text("导出你自己的组合",22,Ui.Ink));body.Children.Add(Ui.Text("包含所选组件的内容、样式和相对位置。番茄钟进度和待办勾选会在安装后重新开始。",12,Ui.Muted));var title=Ui.Input("我的桌面组合");body.Children.Add(title);var checks=new List<Tuple<CheckBox,DesktopWidget>>();foreach(var w in widgets){var check=new CheckBox(){Content=w.Name,IsChecked=true,Margin=new Thickness(0,0,0,10)};checks.Add(Tuple.Create(check,w));body.Children.Add(check);}body.Children.Add(Ui.Button("导出组合包",delegate{try{SaveComponentPack(ComponentPackages.Export(controller.Store.Data,checks.Where(x=>x.Item1.IsChecked==true).Select(x=>x.Item2),title.Text.Trim()),window);window.Close();}catch(Exception ex){Ui.Info(ex.Message,window);}}));window.Content=new ScrollViewer(){Content=body};window.ShowDialog();}
    void CreateComponentPlugin(Window owner){var window=Ui.Dialog("制作组件插件",530,600,owner);var body=new StackPanel(){Margin=new Thickness(24)};body.Children.Add(Ui.Text("把一个小想法做成插件",22,Ui.Ink));var title=Ui.Input("今天吃什么");body.Children.Add(Ui.Text("插件名称",12,Ui.Muted));body.Children.Add(title);var kinds=WidgetPlugins.SupportedKinds;var labels=new[]{"时钟","日历","天气","便签","倒计时","待办清单","番茄钟","随机选择器","计算器","习惯打卡","系统状态","照片轮播","网易云音乐"};var type=Choice(body,"组件类型",labels,7);var text=Ui.Input("面条\n米饭\n饺子\n沙拉");text.AcceptsReturn=true;text.Height=130;body.Children.Add(Ui.Text("内容 / 选项（待办和随机选择器每行一项）",12,Ui.Muted));body.Children.Add(text);var accent=Ui.Input("#B8A1DA");body.Children.Add(Ui.Text("主题颜色",12,Ui.Muted));body.Children.Add(accent);body.Children.Add(Ui.Button("保存到组件库",delegate{try{var plugin=new WidgetPlugin(){Id="custom-"+Guid.NewGuid().ToString("N").Substring(0,12),Name=title.Text.Trim(),Kind=kinds[type.SelectedIndex],Text=text.Text,Accent=accent.Text.Trim(),Description="我制作的桌面小组件"};WidgetPlugins.ValidatePlugin(plugin);controller.Store.Checkpoint();WidgetPlugins.Import(controller.Store.Data,plugin);SaveSettings(false);window.Close();if(owner!=this)owner.Close();else ShowSettingsPage("插件与组件");SetStatus("插件已创建，可在组件卡片上点击分享。");}catch(Exception ex){Ui.Info(ex.Message,window);}}));window.Content=new ScrollViewer(){Content=body};window.ShowDialog();}
    public void ShowComponentMenu(Window owner,Point point){var menu=new ContextMenu(){Placement=PlacementMode.AbsolutePoint,HorizontalOffset=point.X,VerticalOffset=point.Y};menu.Items.Add(Ui.Menu("＋ 选择组件 / 自由组合",delegate{ShowComponentPicker();}));var quick=new MenuItem(){Header="快速添加"};foreach(var plugin in WidgetPlugins.All(controller.Store.Data).Where(x=>x.Enabled)){string id=plugin.Id;quick.Items.Add(Ui.Menu(plugin.Name,delegate{AddComponentPlugins(new[]{id});}));}menu.Items.Add(quick);menu.Items.Add(new Separator());menu.Items.Add(Ui.Menu("安装组件 / 组合包",delegate{InstallComponentFile(this);}));menu.Items.Add(Ui.Menu("导出桌面组合",delegate{ExportComponentSelection(this);}));menu.Items.Add(Ui.Menu("使用教程",delegate{ShowTutorial();}));menu.IsOpen=true;}
}
}
